export const c12EngF1HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.8; color: #E2E8F0; max-width: 950px; margin: 0 auto; padding: 12px; font-size: 15.5px;\">\n\n  <!-- Chapter Header Badge -->\n  <div style=\"background: linear-gradient(135deg, rgba(255, 81, 47, 0.22), rgba(221, 36, 118, 0.1)); border: 1.5px solid #FF512F; border-radius: 12px; padding: 20px; margin-bottom: 25px; box-shadow: 0 4px 22px rgba(255, 81, 47, 0.15);\">\n    <div style=\"display: flex; align-items: center; gap: 10px; margin-bottom: 8px;\">\n      <span style=\"background: #FF512F; color: #000; font-size: 12px; font-weight: 800; padding: 4px 10px; border-radius: 6px; letter-spacing: 0.5px;\">FLAMINGO &bull; PROSE CHAPTER 1</span>\n      <span style=\"color: #94A3B8; font-size: 13.5px; font-weight: 600;\">CLASS XII ENGLISH CORE</span>\n    </div>\n    <h1 style=\"color: #FFFFFF; font-size: 26px; font-weight: 900; margin: 0 0 6px 0; letter-spacing: -0.5px;\">The Last Lesson</h1>\n    <p style=\"color: #CBD5E1; font-size: 15px; margin: 0; font-style: italic;\">\n      By Alphonse Daudet (1840&ndash;1897, France) &mdash; Franco-Prussian War, Linguistic Chauvinism &amp; Mother Tongue as the Citadel of Freedom\n    </p>\n  </div>\n\n  <!-- Quick Glossary & Chapter Dossier Card -->\n  <div style=\"background: rgba(15, 23, 42, 0.92); border: 1.5px solid rgba(255, 81, 47, 0.4); border-radius: 10px; padding: 18px 20px; margin-bottom: 25px; box-shadow: 0 4px 20px rgba(0,0,0,0.35);\">\n    <h3 style=\"color: #FF512F; font-size: 18px; margin: 0 0 12px 0; display: flex; align-items: center; gap: 8px;\">\n      <span>📖</span> Quick Glossary &amp; Chapter Dossier: The Last Lesson\n    </h3>\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; font-size: 14px; color: #CBD5E1;\">\n      <div><b style=\"color: #FF512F;\">Author:</b> Alphonse Daudet (1840&ndash;1897, French Novelist &amp; Storyteller)</div>\n      <div><b style=\"color: #FF512F;\">Historical Setting:</b> Franco-Prussian War (1870&ndash;1871), Fall of Alsace &amp; Lorraine</div>\n      <div><b style=\"color: #FF512F;\">Geographical Setting:</b> An elementary village school in rural Alsace, Eastern France</div>\n      <div><b style=\"color: #FF512F;\">Protagonist:</b> Franz (Reluctant, carefree young schoolboy)</div>\n      <div><b style=\"color: #FF512F;\">The Teacher:</b> M. Hamel (Stern, devoted French schoolmaster of 40 years)</div>\n      <div><b style=\"color: #FF512F;\">Central Concept:</b> Linguistic Chauvinism &mdash; Forcible imposition of German</div>\n      <div><b style=\"color: #FF512F;\">Master Metaphor:</b> <i>\"When a people are enslaved, their language is the key to their prison.\"</i></div>\n      <div><b style=\"color: #FF512F;\">Climax:</b> M. Hamel writing <b>\"VIVE LA FRANCE!\"</b> on the blackboard as bells toll noon</div>\n    </div>\n  </div>\n\n  <!-- Section 1: Executive Summary & Historical Context -->\n  <h2 style=\"color: #FF512F; font-size: 20px; font-weight: 800; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    1. Executive Summary &amp; Historical Framework\n  </h2>\n  <p>\n    <b style=\"color: #FF512F;\">'The Last Lesson'</b> by distinguished French author <b style=\"color: #FF512F;\">Alphonse Daudet</b> is a heart-rending masterpiece examining the devastating cultural and emotional impact of geopolitical warfare upon ordinary human lives. Set during the tragic aftermath of the <b style=\"color: #FF512F;\">Franco-Prussian War (1870&ndash;1871)</b>, in which France was vanquished by Prussian forces led by Chancellor Otto von Bismarck, the story captures the annexation of the French border districts of <b style=\"color: #FF512F;\">Alsace</b> and <b style=\"color: #FF512F;\">Lorraine</b>.\n  </p>\n  <p>\n    Following the conquest, a draconian decree was issued from Berlin mandating that henceforth only the German language would be taught in all educational institutions across Alsace and Lorraine, abruptly banishing the French mother tongue. Rather than depicting grand battlefields or military maneuvers, Daudet filters this national catastrophe through the tender, innocent consciousness of a young schoolboy, <b style=\"color: #FF512F;\">Franz</b>, and the poignant dignity of his devoted teacher, <b style=\"color: #FF512F;\">M. Hamel</b>, who is conducting his final lesson after forty years of dedicated service. Through this micro-history, Daudet exposes the tyranny of <b style=\"color: #FF512F;\">linguistic chauvinism</b>, reminding humanity that a nation's native language is not merely a communicative tool, but the ultimate citadel of its cultural soul and political liberty.\n  </p>\n\n  <!-- Section 2: Chronological Narrative Architecture -->\n  <h2 style=\"color: #FF512F; font-size: 20px; font-weight: 800; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    2. Chronological &amp; Thematic Narrative Architecture\n  </h2>\n\n  <h3 style=\"color: #FF512F; font-size: 17px; margin-top: 22px;\">(i) The Morning of Dread: Nature's Allure vs. Duty</h3>\n  <p>\n    The story opens on a bright, warm morning in rural Alsace. Young <b style=\"color: #FF512F;\">Franz</b> starts late for school in acute dread of being scolded. His strict schoolmaster, <b style=\"color: #FF512F;\">M. Hamel</b>, had announced that he would examine the students on grammatical rules governing <b style=\"color: #FF512F;\">participles</b>&mdash;a topic of which Franz does not know a single word.\n  </p>\n  <p>\n    As Franz hurries along, nature offers intoxicating temptations to play truant: blackbirds are whistling merrily at the edge of the lush woods, and Prussian soldiers are drilling rhythmically in the open meadow behind the sawmill. These outdoor pleasures seem vastly more enticing than dry participle conjugations. Yet, summoning his inner strength, Franz resists the temptation and sprints toward the schoolhouse.\n  </p>\n\n  <h3 style=\"color: #FF512F; font-size: 17px; margin-top: 22px;\">(ii) The Bulletin-Board &amp; The Eerie Sunday Stillness</h3>\n  <p>\n    Passing the town hall, Franz notices a silent crowd gathered before the <b style=\"color: #FF512F;\">bulletin-board</b>. For the past two years, this board had been the harbinger of all catastrophic news: lost battles, military drafts, and oppressive commanding orders from the Prussian headquarters. The village blacksmith, <b style=\"color: #FF512F;\">Wachter</b>, calls out after Franz: <i>\"Don't go so fast, bub; you'll get to your school in plenty of time!\"</i> Franz assumes the blacksmith is mocking his tardiness and arrives breathless at M. Hamel's little garden.\n  </p>\n  <p>\n    Customarily, the school day commenced with a deafening uproar: desks opening and shutting, lessons repeated loudly in unison with hands over ears to concentrate, and the master's heavy iron ruler rapping impatiently against the table. Today, however, an uncanny, solemn stillness blankets the classroom, resembling a quiet Sunday morning. Peering through the window, Franz is astonished to see his classmates already in their seats, while M. Hamel paces back and forth with his ruler tucked beneath his arm.\n  </p>\n\n  <h3 style=\"color: #FF512F; font-size: 17px; margin-top: 22px;\">(iii) The Thunderclap Decree &amp; The Presence of Village Elders</h3>\n  <p>\n    Blushing and terrified, Franz pushes open the door. To his immense surprise, M. Hamel does not scold him; instead, he speaks with unprecedented gentleness: <i>\"Go to your place quickly, little Franz. We were beginning without you.\"</i>\n  </p>\n  <p>\n    As Franz sits down, he notices two extraordinary anomalies:\n  </p>\n  <ul style=\"color: #CBD5E1; font-size: 14.5px; padding-left: 22px; line-height: 1.8;\">\n    <li><b style=\"color: #FF512F;\">Ceremonial Sunday Attire:</b> M. Hamel is dressed in his finest ceremonial clothes&mdash;his beautiful green coat, frilled shirt, and an all-embroidered black silk cap, garments reserved exclusively for school inspections and annual prize-distribution days.</li>\n    <li><b style=\"color: #FF512F;\">Village Elders on the Back Benches:</b> The usually empty rear benches are occupied by village elders: old <b style=\"color: #FF512F;\">Hauser</b> wearing his three-cornered hat and holding a battered, thumbed primer opened across his knees; the former mayor; the former postmaster; and several other respected villagers, all looking intensely sorrowful.</li>\n  </ul>\n  <p>\n    Mounting his platform chair, M. Hamel delivers the earth-shattering announcement: <i>\"My children, this is the last lesson I shall give you. The order has come from Berlin to teach only German in the schools of Alsace and Lorraine. The new master comes tomorrow. This is your last French lesson. I want you to be very attentive.\"</i> These words strike Franz like an agonizing <b style=\"color: #FF512F;\">thunderclap</b>. Overwhelming remorse floods the boy's conscience: he scarcely knows how to write French, yet now his schooling is abruptly cut short. His grammar books and histories of saints, which moments ago seemed an unbearable nuisance, suddenly feel like beloved old companions he can never part with.\n  </p>\n\n  <h3 style=\"color: #FF512F; font-size: 17px; margin-top: 22px;\">(iv) The Recitation Failure &amp; The Philosophy of Language</h3>\n  <p>\n    When his name is called to recite the dreadful rule of participles, Franz desperately wishes he could utter the grammar rules cleanly without a flaw. Instead, he stumbles on the very first word and stands holding his desk, his heart pounding violently in acute shame.\n  </p>\n  <p>\n    M. Hamel does not scold him, remarking sorrowfully: <i>\"I won't scold you, little Franz; you must feel bad enough. See how it is! Every day we have said to ourselves: 'Bah! I've plenty of time. I'll learn it tomorrow.' And now you see where we've come out.\"</i>\n  </p>\n  <p>\n    M. Hamel distributes the blame with profound moral integrity. He reproaches parents who prioritized sending children to work in cotton mills or farms for extra sous, and candidly reproaches himself for frequently giving students holidays to go trout fishing or sending Franz to water his garden flowers. He then delivers his impassioned tribute to the French tongue, proclaiming it to be <b style=\"color: #FF512F;\">the most beautiful, clearest, and most logical language in the entire world</b>. He commands them to guard it sacredly among themselves, stating his immortal maxim:\n  </p>\n  <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 4px solid #FF512F; padding: 14px 18px; margin: 16px 0; border-radius: 6px; font-style: italic; color: #FFE0B2;\">\n    \"When a people are enslaved, as long as they hold fast to their language, it is as if they had the key to their prison.\"\n  </div>\n\n  <h3 style=\"color: #FF512F; font-size: 17px; margin-top: 22px;\">(v) The Final Climax: Midnight Bells &amp; 'Vive La France!'</h3>\n  <p>\n    The master conducts a grammar lesson so luminous that Franz understands every concept effortlessly. Next comes writing practice. M. Hamel distributes new copybooks inscribed in beautiful round hand: <b style=\"color: #FF512F;\">France, Alsace, France, Alsace</b>. The copies flutter from the desks like tiny national banners. Even when some beetles fly in through the open window, nobody pays them any attention; the entire room is submerged in rapt, solemn concentration.\n  </p>\n  <p>\n    On the roof, pigeons coo softly, inspiring Franz's legendary satirical reflection: <i>\"Will they make them sing in German, even the pigeons?\"</i> Looking up, Franz observes M. Hamel gazing motionless at every object in the classroom&mdash;the walnut trees in the garden, the hopvine twining around the windows&mdash;committing forty years of cherished memories to his heart. Overhead in the attic, his sister can be heard packing their trunks, for they must leave the country the very next day.\n  </p>\n  <p>\n    Suddenly, the village church clock strikes <b style=\"color: #FF512F;\">twelve</b>, followed immediately by the Angelus chimes. At that precise instant, the triumphant trumpets of Prussian soldiers returning from drill sound beneath the classroom windows. M. Hamel rises from his chair, deathly pale. He tries to speak: <i>\"My friends... I... I...\"</i> But suffocating emotion chokes his voice. Turning to the blackboard, he grasps a piece of chalk and, bearing on with all his strength, writes in colossal letters:\n  </p>\n  <div style=\"text-align: center; margin: 20px 0;\">\n    <span style=\"font-size: 28px; font-weight: 900; color: #FF512F; letter-spacing: 2px; text-shadow: 0 0 15px rgba(255, 81, 47, 0.4);\">\n      \"VIVE LA FRANCE!\"\n    </span>\n  </div>\n  <p>\n    Overcome with monumental grief, he leans his head against the wall and, without a word, makes a simple gesture with his hand: <i>\"School is dismissed &mdash; you may go.\"</i>\n  </p>\n\n  <!-- Section 3: Psychological Character Profiles -->\n  <h2 style=\"color: #FF512F; font-size: 20px; font-weight: 800; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    3. Psychological Character Sketches &amp; Profiles\n  </h2>\n\n  <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; margin-bottom: 25px;\">\n    \n    <!-- M. Hamel -->\n    <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 81, 47, 0.3); border-radius: 8px; padding: 16px;\">\n      <h3 style=\"color: #FF512F; font-size: 17px; margin: 0 0 8px 0;\">1. M. Hamel (The Patriotic Schoolmaster)</h3>\n      <p style=\"font-size: 14px; margin: 0; color: #CBD5E1;\">\n        Initially viewed by students as strict and cranky with his iron ruler, M. Hamel emerges during his final lesson as an ardent patriot and philosopher of linguistic dignity. For forty years he nurtured Alsace's youth. Rather than projecting anger onto students, he courageously shares the blame for neglected education. His ceremonial Sunday attire and monumental final inscription on the blackboard embody heroic defiance and dignified grief.\n      </p>\n    </div>\n\n    <!-- Franz -->\n    <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 81, 47, 0.3); border-radius: 8px; padding: 16px;\">\n      <h3 style=\"color: #FF512F; font-size: 17px; margin: 0 0 8px 0;\">2. Franz (The Awakened Adolescent)</h3>\n      <p style=\"font-size: 14px; margin: 0; color: #CBD5E1;\">\n        A carefree, procrastinating schoolboy easily distracted by birds and drilling soldiers. When the Berlin decree is unveiled, he undergoes an instantaneous psychological awakening. His childish resentment of grammar transforms into reverence, intellectual maturity, and deep patriotic sorrow. He realizes the profound value of his mother tongue only when it is forcibly stripped away.\n      </p>\n    </div>\n\n    <!-- Village Elders -->\n    <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 81, 47, 0.3); border-radius: 8px; padding: 16px;\">\n      <h3 style=\"color: #FF512F; font-size: 17px; margin: 0 0 8px 0;\">3. Old Hauser &amp; The Village Elders</h3>\n      <p style=\"font-size: 14px; margin: 0; color: #CBD5E1;\">\n        Old Hauser, holding his worn primer, together with the former mayor and postmaster, represent the collective conscience of Alsace. Their presence on the classroom back benches symbolizes communal repentance for neglected schooling and a solemn farewell tribute to M. Hamel's lifetime of faithful service to the French nation.\n      </p>\n    </div>\n\n  </div>\n\n  <!-- Section 4: Literary & Rhetorical Devices Master Table -->\n  <h2 style=\"color: #FF512F; font-size: 20px; font-weight: 800; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    4. Literary &amp; Rhetorical Devices Master Table\n  </h2>\n  <div style=\"overflow-x: auto; margin-bottom: 25px;\">\n    <table style=\"width: 100%; border-collapse: collapse; font-size: 14.5px; text-align: left; background: rgba(15, 23, 42, 0.9); border-radius: 8px; overflow: hidden;\">\n      <thead>\n        <tr style=\"background: rgba(255, 81, 47, 0.25); color: #FFFFFF; border-bottom: 2px solid #FF512F;\">\n          <th style=\"padding: 12px 14px;\">Literary Device</th>\n          <th style=\"padding: 12px 14px;\">Textual Quote / Example</th>\n          <th style=\"padding: 12px 14px;\">Literary &amp; Thematic Effect</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #FF512F;\">Extended Metaphor</td>\n          <td style=\"padding: 12px 14px;\">\"...it is as if they had the key to their prison.\"</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">Compares a conquered nation's mother tongue to an escape key, symbolizing intellectual and spiritual emancipation from colonial bondage.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #FF512F;\">Simile</td>\n          <td style=\"padding: 12px 14px;\">\"...looked like little flags floating everywhere in the school-room...\"</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">Compares the writing copybooks inscribed with 'France, Alsace' to national flags, turning the classroom into a patriotic sanctuary.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #FF512F;\">Satirical Irony &amp; Pathos</td>\n          <td style=\"padding: 12px 14px;\">\"Will they make them sing in German, even the pigeons?\"</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">Exposes the tyrannical absurdity of linguistic chauvinism attempting to subjugate free nature and the human spirit.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #FF512F;\">Dramatic Irony</td>\n          <td style=\"padding: 12px 14px;\">Franz assuming Wachter the blacksmith was mocking him when told not to hurry.</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">The reader and blacksmith know the tragic Berlin decree, while Franz is initially in blissful, tragic ignorance.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #FF512F;\">Symbolism</td>\n          <td style=\"padding: 12px 14px;\">M. Hamel's embroidered green coat, frilled shirt, and black silk cap.</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">Symbolizes formal reverence, solemn honor, and collective mourning for the demise of French education in Alsace.</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n\n  <!-- Section 5: Board Exam Strategy & High-Scoring Tips Box -->\n  <div style=\"background: rgba(15, 23, 42, 0.92); border-left: 5px solid #FF512F; border-radius: 8px; padding: 18px 20px; margin-bottom: 25px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #FF512F; font-size: 18px; margin: 0 0 10px 0; display: flex; align-items: center; gap: 8px;\">\n      <span>🎯</span> Board Examination Master Tips: Scoring 100% in The Last Lesson\n    </h3>\n    <ul style=\"color: #CBD5E1; font-size: 14.5px; padding-left: 20px; margin: 0; line-height: 1.8;\">\n      <li><b style=\"color: #FF512F;\">Linguistic Chauvinism Definition:</b> Define linguistic chauvinism clearly as <b style=\"color: #FF512F;\">the aggressive, forced imposition of a conqueror's language over a defeated people</b>.</li>\n      <li><b style=\"color: #FF512F;\">Quote the Prison Key Metaphor:</b> Always include the exact quote: <i>\"...as long as they hold fast to their language it is as if they had the key to their prison.\"</i></li>\n      <li><b style=\"color: #FF512F;\">Explain the Village Elders' Motive:</b> Remember that the elders attended not out of curiosity, but out of <b style=\"color: #FF512F;\">repentance for lost schooling</b> and to <b style=\"color: #FF512F;\">thank M. Hamel for 40 years of service</b>.</li>\n    </ul>\n  </div>\n\n</div>\n";

export const c12EngF1HtmlSolutions = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-left: left !important; }\n</style>\n\n<div style=\"font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.8; color: #E2E8F0; max-width: 950px; margin: 0 auto; padding: 12px; font-size: 15.5px;\">\n\n  <!-- Section Header Badge -->\n  <div style=\"background: linear-gradient(135deg, rgba(255, 81, 47, 0.22), rgba(221, 36, 118, 0.1)); border-left: 5px solid #FF512F; padding: 16px 20px; border-radius: 8px; margin-bottom: 25px;\">\n    <h2 style=\"color: #FF512F; font-weight: 900; margin: 0 0 4px 0; font-size: 21px;\">\n      BOARD EXAMINATION QUESTIONS &amp; MODEL ANSWERS\n    </h2>\n    <span style=\"color: #94A3B8; font-size: 14px; font-weight: 600;\">Standardized to CBSE &amp; JKBOSE Class XII English Core Blueprint &bull; Theme Color Standardized</span>\n  </div>\n\n  <!-- SECTION A: EXTRACT-BASED QUESTIONS -->\n  <h2 style=\"color: #FF512F; font-size: 20px; font-weight: 800; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin: 26px 0 16px 0;\">\n    SECTION A: Extract-Based Objective Questions (1 Mark Each)\n  </h2>\n\n  <!-- Extract 1 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(255, 81, 47, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #FF512F;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #FF512F;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"While I was thinking of all this, I heard my name called. It was my turn to recite. What would I not have given to be able to say that dreadful rule for the participle all through, very loud and clear, and without one mistake? But I got mixed up on the first words and stood there, holding on to my desk, my heart beating, and not daring to look up.\"\n    </p>\n    \n    <p>\n      <b style=\"color: #FF512F; font-size: 15px;\">Q1: What was Franz called upon to recite by his teacher?</b><br/>\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> The grammatical rules governing <b style=\"color: #FF512F;\">participles</b>.\n    </p>\n\n    <p>\n      <b style=\"color: #FF512F; font-size: 15px;\">Q2: Why did Franz get mixed up on the very first words?</b><br/>\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> Because he had constantly procrastinated, never studying his grammar, and knew nothing about participles.\n    </p>\n\n    <p>\n      <b style=\"color: #FF512F; font-size: 15px;\">Q3: What physical gesture demonstrated Franz's acute shame and embarrassment?</b><br/>\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> He held on to his desk with his heart pounding heavily, not daring to lift his eyes to face M. Hamel.\n    </p>\n\n    <p>\n      <b style=\"color: #FF512F; font-size: 15px;\">Q4: How did M. Hamel react to Franz's failure to recite?</b><br/>\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> Instead of scolding him, M. Hamel expressed sorrow, lamenting the habit of postponing learning until tomorrow.\n    </p>\n  </div>\n\n  <!-- Extract 2 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(255, 81, 47, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #FF512F;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #FF512F;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"Once some beetles flew in; but nobody paid any attention to them, not even the littlest ones, who worked right on tracing their fish-hooks, as if that was French, too. On the roof the pigeons cooed very low, and I thought to myself, 'Will they make them sing in German, even the pigeons?'\"\n    </p>\n    \n    <p>\n      <b style=\"color: #FF512F; font-size: 15px;\">Q5: What shows the unprecedented degree of concentration inside the classroom?</b><br/>\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> Even when beetles flew in, nobody paid attention&mdash;not even the youngest children tracing their fish-hooks.\n    </p>\n\n    <p>\n      <b style=\"color: #FF512F; font-size: 15px;\">Q6: What literary device is exemplified in Franz's thought regarding the pigeons?</b><br/>\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> Satirical irony and pathos, exposing the tyrannical vanity of trying to subjugate free nature.\n    </p>\n\n    <p>\n      <b style=\"color: #FF512F; font-size: 15px;\">Q7: What does Franz's reflection reveal about linguistic chauvinism?</b><br/>\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> It reveals that political conquerors may annex territory, but cannot enslave the natural soul or mother tongue of a people.\n    </p>\n\n    <p>\n      <b style=\"color: #FF512F; font-size: 15px;\">Q8: What were the youngest children tracing in their copybooks?</b><br/>\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> They were diligently tracing their <b style=\"color: #FF512F;\">fish-hooks</b> with unbroken concentration.\n    </p>\n  </div>\n\n  <!-- Extract 3 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(255, 81, 47, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #FF512F;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #FF512F;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"My children, this is the last lesson I shall give you. The order has come from Berlin to teach only German in the schools of Alsace and Lorraine. The new master comes tomorrow. This is your last French lesson. I want you to be very attentive.\"\n    </p>\n    \n    <p>\n      <b style=\"color: #FF512F; font-size: 15px;\">Q9: Where had the order to ban French instruction originated?</b><br/>\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> The imperial order originated from the Prussian capital of <b style=\"color: #FF512F;\">Berlin</b>.\n    </p>\n\n    <p>\n      <b style=\"color: #FF512F; font-size: 15px;\">Q10: Which two French border districts were subjected to this decree?</b><br/>\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> The French frontier districts of <b style=\"color: #FF512F;\">Alsace</b> and <b style=\"color: #FF512F;\">Lorraine</b>.\n    </p>\n\n    <p>\n      <b style=\"color: #FF512F; font-size: 15px;\">Q11: How did these words affect Franz when they were spoken?</b><br/>\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> They fell upon him like an agonizing <b style=\"color: #FF512F;\">thunderclap</b>, inducing sudden guilt and sorrow.\n    </p>\n\n    <p>\n      <b style=\"color: #FF512F; font-size: 15px;\">Q12: When was the new German master scheduled to take charge?</b><br/>\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> The new German master was scheduled to arrive the very next day.\n    </p>\n  </div>\n\n  <!-- Extract 4 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(255, 81, 47, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #FF512F;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #FF512F;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"Then he turned to the blackboard, took a piece of chalk, and, bearing on with all his might, he wrote as large as he could: 'VIVE LA FRANCE!' Then he stopped and leaned his head against the wall, and, without a word, he made a gesture to us with his hand: 'School is dismissed &mdash; you may go.'\"\n    </p>\n    \n    <p>\n      <b style=\"color: #FF512F; font-size: 15px;\">Q13: What iconic patriotic phrase did M. Hamel inscribe on the blackboard?</b><br/>\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> <b style=\"color: #FF512F;\">\"VIVE LA FRANCE!\"</b> (Long Live France!).\n    </p>\n\n    <p>\n      <b style=\"color: #FF512F; font-size: 15px;\">Q14: Why did M. Hamel write in the largest letters possible?</b><br/>\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> To pour all his defiance, patriotic passion, and grief into a monumental visual declaration of French sovereignty.\n    </p>\n\n    <p>\n      <b style=\"color: #FF512F; font-size: 15px;\">Q15: Why did M. Hamel stop and lean his head against the wall without speaking?</b><br/>\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> He was suffocated by overwhelming emotional grief and could not articulate spoken words.\n    </p>\n\n    <p>\n      <b style=\"color: #FF512F; font-size: 15px;\">Q16: How did M. Hamel dismiss the classroom at the conclusion?</b><br/>\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> In silence, with a weary, poignant gesture of his hand.\n    </p>\n  </div>\n\n  <!-- SECTION B: SHORT ANSWER QUESTIONS -->\n  <h2 style=\"color: #FF512F; font-size: 20px; font-weight: 800; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    SECTION B: Short Answer Questions (3 Marks Each | 40&ndash;50 Words)\n  </h2>\n\n  <!-- Q17 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FF512F;\">\n    <h4 style=\"color: #FF512F; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q17: What tempted Franz to play truant from school on that morning?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> Franz had not prepared his lesson on participles and feared M. Hamel's reprimands. Outside, the weather was warm and bright; blackbirds were chirping at the edge of the woods, and Prussian soldiers were drilling behind the sawmill, offering temptations far more inviting than grammar.\n    </p>\n  </div>\n\n  <!-- Q18 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FF512F;\">\n    <h4 style=\"color: #FF512F; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q18: What uncanny sights greeted Franz when he reached the school?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> Instead of the customary commotion of opening desks and lessons chanted in unison, an uncanny Sunday morning silence prevailed. Classmates were seated, M. Hamel wore his formal ceremonial Sunday attire, and village elders sat sorrowfully on the back benches.\n    </p>\n  </div>\n\n  <!-- Q19 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FF512F;\">\n    <h4 style=\"color: #FF512F; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q19: Why were the village elders occupying the rear benches of the classroom?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> The elders attended to express repentance for neglecting their education in youth. It was their collective way of honoring M. Hamel for forty years of devoted service and paying tribute to their French mother tongue, which was being ripped away by Prussian decrees.\n    </p>\n  </div>\n\n  <!-- Q20 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FF512F;\">\n    <h4 style=\"color: #FF512F; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q20: Whom did M. Hamel hold responsible for the neglect of French learning in Alsace?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> M. Hamel blamed parents who prioritized sending children to work in cotton mills or farms for extra money. Courageously, he also blamed himself for frequently giving holidays to go fishing, and criticized the habitual procrastination of Alsace citizens who put off learning until tomorrow.\n    </p>\n  </div>\n\n  <!-- Q21 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FF512F;\">\n    <h4 style=\"color: #FF512F; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q21: What praise did M. Hamel bestow upon the French language?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> M. Hamel praised French as <b style=\"color: #FF512F;\">the most beautiful, clearest, and most logical language</b> in the world. He urged his people to guard it sacredly, asserting that as long as an enslaved people cling to their language, they hold the key to unlock their prison.\n    </p>\n  </div>\n\n  <!-- Q22 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FF512F;\">\n    <h4 style=\"color: #FF512F; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q22: How did Franz's feelings toward M. Hamel and his books change after the announcement?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> The announcement transformed Franz's hostility into love and remorse. His grammar books and histories of saints, which moments ago seemed burdensome nuisances, suddenly felt like beloved old friends. His fear of M. Hamel's ruler dissolved into profound respect for his sorrow and patriotism.\n    </p>\n  </div>\n\n  <!-- Q23 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FF512F;\">\n    <h4 style=\"color: #FF512F; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q23: What was the significance of M. Hamel's ceremonial green coat and black silk cap?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> Reserved exclusively for prize-distribution and inspection days, this ceremonial attire was worn as a solemn mark of honor for his final French lesson. It symbolized deep reverence for his calling and functioned as formal mourning for the demise of French education in Alsace.\n    </p>\n  </div>\n\n  <!-- Q24 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FF512F;\">\n    <h4 style=\"color: #FF512F; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q24: What was written in the new copies distributed during the writing lesson?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> M. Hamel had prepared new copies inscribed in beautiful round hand: <b style=\"color: #FF512F;\">France, Alsace, France, Alsace</b>. Resting on the desks, they looked like little national flags fluttering throughout the room, transforming the classroom into a sanctuary of patriotic solidarity.\n    </p>\n  </div>\n\n  <!-- Q25 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FF512F;\">\n    <h4 style=\"color: #FF512F; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q25: Explain Franz's thought: 'Will they make them sing in German, even the pigeons?'</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> This biting reflection mocks Prussian linguistic chauvinism. Franz satirizes the tyrannical vanity of imperial colonizers, emphasizing that while foreign rulers can seize political territory, they can never conquer nature, animal instincts, or the innate cultural spirit of a free people.\n    </p>\n  </div>\n\n  <!-- Q26 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FF512F;\">\n    <h4 style=\"color: #FF512F; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q26: What sounds announced the conclusion of the last lesson?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> The church clock chimed <b style=\"color: #FF512F;\">twelve</b>, followed immediately by the Angelus prayer bells. Simultaneously, the blaring trumpets of Prussian soldiers returning from drill sounded beneath the classroom windows, marking the end of French instruction.\n    </p>\n  </div>\n\n  <!-- Q27 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FF512F;\">\n    <h4 style=\"color: #FF512F; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q27: How did M. Hamel bid farewell to his class at the climax?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> Choking with tears, M. Hamel turned to the blackboard and wrote <b style=\"color: #FF512F;\">\"VIVE LA FRANCE!\"</b> in colossal letters with all his strength. Leaning his head against the wall in overwhelming grief, he silently dismissed the school with a wave of his hand.\n    </p>\n  </div>\n\n  <!-- Q28 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FF512F;\">\n    <h4 style=\"color: #FF512F; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q28: What is the core moral message of 'The Last Lesson'?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> The story warns against the perils of procrastination in education and highlights that a mother tongue is the sacred citadel of identity and freedom. We only realize the true value of our linguistic heritage when it is on the verge of being lost forever.\n    </p>\n  </div>\n\n  <!-- SECTION C: LONG ANSWER QUESTIONS -->\n  <h2 style=\"color: #FF512F; font-size: 20px; font-weight: 800; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    SECTION C: Long Answer / Thematic Questions (6 Marks Each | 120&ndash;150 Words)\n  </h2>\n\n  <!-- Q29 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(255, 81, 47, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #FF512F; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q29: Trace the transformation in Franz's attitude toward M. Hamel, his books, and French in 'The Last Lesson'.\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #FF512F;\">Model Answer:</b><br/>\n      <b>1. Initial Carefree Indifference:</b> At the beginning of the story, Franz represents a typical irresponsible schoolboy who chronically procrastinates. Dreading grammar rules and participles, he actively considers playing truant to enjoy the sunny outdoors and drilling soldiers. He views M. Hamel as a cranky, severe disciplinarian armed with an intimidating iron ruler.<br/><br/>\n      <b>2. The Thunderclap Awakening:</b> When M. Hamel announces the Berlin decree banishing French from Alsace and Lorraine, Franz experiences a profound psychological shock. A wave of acute remorse overwhelms him for skipped lessons and wasted days. His old grammar book and histories of saints, which minutes ago seemed unbearable burdens, suddenly feel like beloved old companions he can never abandon.<br/><br/>\n      <b>3. Reverence &amp; Maturity:</b> Franz listens to the final grammar and writing lessons with rapt concentration, finding French effortlessly intelligible when absorbed with patriotic reverence. His childish resentment dissolves into deep sympathy for M. Hamel's impending exile after forty years of service. He matures into an awakened patriot who understands the sacred sanctity of his mother tongue.\n    </p>\n  </div>\n\n  <!-- Q30 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(255, 81, 47, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #FF512F; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q30: Examine 'Linguistic Chauvinism' as depicted in 'The Last Lesson'. Why is mother tongue essential to national freedom?\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #FF512F;\">Model Answer:</b><br/>\n      <b>1. Concept of Linguistic Chauvinism:</b> Linguistic chauvinism refers to the aggressive, arrogant imposition of one community's language upon a conquered people, accompanied by the systematic eradication of their native language. In 'The Last Lesson', the Prussian decree enforcing German in Alsace and Lorraine epitomizes this cultural imperialism.<br/><br/>\n      <b>2. The Mother Tongue as a Citadel:</b> Alphonse Daudet demonstrates that language is not merely a vehicle for communication, but the living repository of a civilization's heritage, history, and identity. M. Hamel eloquently observes that when a people are enslaved, holding fast to their language is akin to holding the key to their prison. The mother tongue sustains collective solidarity and fuels resistance against subjugation.<br/><br/>\n      <b>3. Universal Truth:</b> Franz's biting thought about the pigeons on the roof exposes the absurdity of linguistic chauvinism. Conquerors can seize land through military force, but they can never subjugate the inherent nature, soul, and mother tongue of a free people.\n    </p>\n  </div>\n\n  <!-- Q31 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(255, 81, 47, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #FF512F; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q31: Characterize M. Hamel as a teacher, patriot, and human being based on 'The Last Lesson'.\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #FF512F;\">Model Answer:</b><br/>\n      <b>1. As a Dedicated Teacher:</b> M. Hamel served the school of Alsace for forty continuous years with steadfast devotion. Though initially perceived as strict and quick-tempered with his iron ruler, his pedagogy during the final lesson displays extraordinary patience, lucidity, and pedagogical passion, making complex grammar accessible to all.<br/><br/>\n      <b>2. Moral Honesty &amp; Self-Reproach:</b> Unlike ordinary men who deflect blame onto others, M. Hamel displays rare moral courage. He shares the blame for the villagers' neglected French education, candidly admitting his own faults in giving holidays for fishing and sending pupils to water his flowers.<br/><br/>\n      <b>3. An Ardent Patriot:</b> Wearing his finest ceremonial green coat and black silk cap to honor his mother tongue, M. Hamel stands as a titan of patriotism. His impassioned praise of French and his climactic inscription of 'VIVE LA FRANCE!' on the blackboard elevate him into an immortal symbol of dignity, resilience, and unyielding national honor.\n    </p>\n  </div>\n\n  <!-- Q32 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(255, 81, 47, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #FF512F; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q32: Discuss the significance of the presence of the village elders on the back benches during the last lesson.\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #FF512F;\">Model Answer:</b><br/>\n      <b>1. An Unusual Spectacle:</b> The presence of old Hauser, the former mayor, the former postmaster, and other village elders sitting quietly on the usually vacant back benches provides the story with profound emotional gravity.<br/><br/>\n      <b>2. Motives for Attendance:</b> The elders attended for three vital reasons: first, to express genuine repentance for not attending school more often during their youth; second, to pay tribute to M. Hamel for forty years of devoted service; and third, to demonstrate solemn respect for their native country and mother tongue, which was being ripped away by Prussian decrees.<br/><br/>\n      <b>3. The Primers of Repentance:</b> Old Hauser sitting with his thumbed primer across his knees, spelling letters alongside the youngest children with spectacles balanced on his nose, captures the heartbreaking tragedy of learning too late. Their presence transforms an ordinary school session into a communal funeral for their cultural liberty.\n    </p>\n  </div>\n\n  <!-- Q33 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(255, 81, 47, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #FF512F; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q33: How does Alphonse Daudet create an atmosphere of poignant suspense and sorrow leading up to the story's climax?\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #FF512F;\">Model Answer:</b><br/>\n      <b>1. Establishing the Eerie Stillness:</b> Daudet builds suspense by replacing the customary morning classroom clamor with an eerie, church-like silence, immediately alerting Franz and the reader that an extraordinary event is unfolding.<br/><br/>\n      <b>2. Visual &amp; Auditory Details:</b> The author layers poignant details: M. Hamel's embroidered Sunday coat, the sorrowful village elders holding battered primers, the copybooks fluttering like little flags, and M. Hamel's sister packing trunks in the attic above. Auditory cues like the cooing pigeons and buzzing beetles highlight the breathless concentration of the students.<br/><br/>\n      <b>3. The Dramatic Climax:</b> The suspense culminates when the church clock strikes twelve, followed by the Angelus and the blaring Prussian trumpets. M. Hamel rising pale, choking with tears, and writing 'VIVE LA FRANCE!' with all his might produces an unforgettable climax of tragic beauty and patriotic triumph.\n    </p>\n  </div>\n\n  <!-- Q34 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(255, 81, 47, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #FF512F; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q34: 'Procrastination is the thief of time and opportunity.' How is this truth brought out in 'The Last Lesson'?\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #FF512F;\">Model Answer:</b><br/>\n      <b>1. The Habit of Delay:</b> In 'The Last Lesson', procrastination is highlighted as the fatal flaw that cost Alsace its linguistic heritage. M. Hamel laments that every day the citizens told themselves: <i>\"Bah! I've plenty of time. I'll learn it tomorrow.\"</i><br/><br/>\n      <b>2. The Tragic Realization:</b> Parents delayed schooling to send children to work for extra sous; Franz delayed studying participles to chase birds; and M. Hamel delayed lessons to go fishing. Everyone assumed tomorrow would always offer another opportunity to learn.<br/><br/>\n      <b>3. Irreversible Loss:</b> When the sudden Berlin decree revokes the right to learn French overnight, procrastination exacts its brutal penalty. The villagers are left with hollow regrets and illiterate shame. Daudet delivers a timeless warning: education and cultural privileges must never be postponed, for when opportunity vanishes, remorse is powerless to reclaim lost time.\n    </p>\n  </div>\n\n  <!-- SECTION D: NCERT TEXTBOOK EXERCISES -->\n  <h2 style=\"color: #FF512F; font-size: 20px; font-weight: 800; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    SECTION D: NCERT Textbook Exercises (Official Solutions)\n  </h2>\n\n  <!-- NCERT Q1 -->\n  <div style=\"margin-bottom: 18px; background: rgba(15, 23, 42, 0.55); border-left: 4px solid #FF512F; padding: 14px 16px; border-radius: 6px;\">\n    <h4 style=\"color: #FF512F; font-size: 15.5px; margin: 0 0 6px 0; font-weight: 700;\">Q35: What was Franz expected to be prepared with for school that day?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> Franz was expected to be thoroughly prepared with the grammatical rules governing <b style=\"color: #FF512F;\">participles</b>, as M. Hamel had announced that he would question the class on them that morning. Franz was terrified because he did not know a single word about them.\n    </p>\n  </div>\n\n  <!-- NCERT Q2 -->\n  <div style=\"margin-bottom: 18px; background: rgba(15, 23, 42, 0.55); border-left: 4px solid #FF512F; padding: 14px 16px; border-radius: 6px;\">\n    <h4 style=\"color: #FF512F; font-size: 15.5px; margin: 0 0 6px 0; font-weight: 700;\">Q36: What had been put up on the bulletin-board?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> The bulletin-board at the town hall displayed the shocking imperial order from Berlin mandating that henceforth only the German language would be taught in all schools of Alsace and Lorraine, effectively terminating French instruction and exiling French teachers.\n    </p>\n  </div>\n\n  <!-- NCERT Q3 -->\n  <div style=\"margin-bottom: 18px; background: rgba(15, 23, 42, 0.55); border-left: 4px solid #FF512F; padding: 14px 16px; border-radius: 6px;\">\n    <h4 style=\"color: #FF512F; font-size: 15.5px; margin: 0 0 6px 0; font-weight: 700;\">Q37: What changes did the order from Berlin cause in school that day?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> The Berlin order cast a somber, church-like silence over the entire school. M. Hamel wore his formal ceremonial green coat and embroidered black silk cap; village elders sat sorrowfully on the rear benches holding old primers; and students listened to their mother tongue with unprecedented reverence and devotion.\n    </p>\n  </div>\n\n  <!-- NCERT Q4 -->\n  <div style=\"margin-bottom: 18px; background: rgba(15, 23, 42, 0.55); border-left: 4px solid #FF512F; padding: 14px 16px; border-radius: 6px;\">\n    <h4 style=\"color: #FF512F; font-size: 15.5px; margin: 0 0 6px 0; font-weight: 700;\">Q38: How did Franz's feelings about M. Hamel and school change?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FF512F; font-weight: bold;\">✓ Answer:</span> Franz was struck with acute guilt and remorse for neglecting his studies. His hatred for grammar transformed into passionate love for the French language, and his fear of M. Hamel's iron ruler dissolved into profound respect, sympathy, and admiration for the schoolmaster's patriotism and sorrow.\n    </p>\n  </div>\n\n</div>\n";

